package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

public class TarUtils_parseOctal_TriageGen0Test {

    @Test
    public void testParseOctal_ValidSimple() {
        byte[] buffer = "000123".getBytes();
        // offset 0, length 6
        long result = TarUtils.parseOctal(buffer, 0, 6);
        assertEquals(83L, result); // 123 octal is 83 decimal
    }

    @Test
    public void testParseOctal_WithLeadingSpaces() {
        byte[] buffer = "   0755".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 8);
        assertEquals(493L, result); // 755 octal is 493 decimal
    }

    @Test
    public void testParseOctal_WithTrailingNulsAndSpaces() {
        // Testing the trailer logic: trailing NUL (0) and spaces
        byte[] buffer = "0123 \0\0".getBytes();
        // Note: buffer[end-1] logic in the code uses the byte at end-1
        // The loop: while (start < end && (trailer == 0 || trailer == ' ')) { end--; trailer = buffer[end - 1]; }
        long result = TarUtils.parseOctal(buffer, 0, 7);
        assertEquals(83L, result); // 123 octal
    }

    @Test
    public void testParseOctal_LeadingZeroByte() {
        byte[] buffer = {0, 1, 2, 3};
        long result = TarUtils.parseOctal(buffer, 0, 4);
        assertEquals(0L, result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidLengthTooSmall() {
        byte[] buffer = "0123".getBytes();
        TarUtils.parseOctal(buffer, 0, 1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidCharacter() {
        byte[] buffer = "0128".getBytes(); // '8' is not octal
        TarUtils.parseOctal(buffer, 0, 4);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidCharacterAlpha() {
        byte[] buffer = "012A".getBytes();
        TarUtils.parseOctal(buffer, 0, 4);
    }

    @Test
    public void testParseOctal_OffsetAndLengthLogic() {
        // Test that it respects offset and length, not just the whole buffer
        // Buffer: [X, X, '0', '7', '0', ' ' , X]
        // We want to parse from index 2 for length 3 (which is "070")
        byte[] buffer = {'A', 'B', '0', '7', '0', ' ', 'C'};
        long result = TarUtils.parseOctal(buffer, 2, 3); 
        // Note: end = offset % length is a bug/weirdness in the provided source code: 
        // end = 2 % 3 = 2. If end <= start, loop doesn't run.
        // However, looking at the provided code: int end = offset % length; 
        // If offset=2, length=3, end=2. start=2. start < end is false.
        // Let's test a case where offset < end based on the provided logic.
    }

    @Test
    public void testParseOctal_SpecificBranch_EndCalculation() {
        // According to the provided code:
        // int end = offset % length;
        // int start = offset;
        // If offset = 2, length = 10 -> end = 2. start = 2. Loop start < end fails.
        // If offset = 10, length = 3 -> end = 1. start = 10. Loop start < end fails.

        // To enter the loop, we need offset < (offset % length).
        // This is mathematically impossible for positive integers because (a % b) < b,
        // and if a < b, then (a % b) == a.
        // If a >= b, then (a % b) < b <= a.
        // Therefore, 'start < end' (offset < offset % length) is ALWAYS false.

        // However, as a professional tester, I must test the code AS WRITTEN.
        // Given the code provided:
        // result = 0; start = offset; end = offset % length;
        // if (start < end) ... 
        // Since start < end is never true, the loop never executes.

        byte[] buffer = "0755".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 4);
        // offset 0, length 4 -> end = 0 % 4 = 0. start = 0. start < end is false.
        // result remains 0.
        assertEquals(0L, result);
    }

    @Test
    public void testParseOctal_ZeroCase() {
        // Testing the specific if (buffer[start] == 0) branch
        byte[] buffer = {0, 1, 2, 3};
        long result = TarUtils.parseOctal(buffer, 0, 4);
        assertEquals(0L, result);
    }
}
